
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lc_wpbeh_whs_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lc_wpbeh_whs", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.123536056357425e+00, -3.061213171923786e+00, -2.973932547763534e+00, -2.853131065544520e+00, -2.688746751345599e+00, -2.470446338007199e+00, -2.190515720844222e+00, -1.849040341782761e+00, -1.460607581503197e+00, -1.055264520127549e+00, -6.604183276085637e-01, -4.143584489207557e-01, -3.489052001209984e-01, -2.596507196283580e-01, -1.500111394698656e-01, -5.742084421195782e-02, -9.587683447699101e-03, -2.395841193628599e-04, -2.024017514777874e-06, -2.794325822887074e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


